COMM_ACC = {}
COMM_ENABLED = {"on": False, "depth": 0}


def _timed_call(name, orig, kind, a, kw):
    if not COMM_ENABLED["on"] or COMM_ENABLED["depth"] > 0:
        COMM_ENABLED["depth"] += 1
        try:
            return orig(*a, **kw)
        finally:
            COMM_ENABLED["depth"] -= 1
    COMM_ENABLED["depth"] += 1
    t0 = time.perf_counter()
    try:
        ret = orig(*a, **kw)
        if kw.get("async_op") and ret is not None:
            ret.wait()
    finally:
        COMM_ENABLED["depth"] -= 1
    dev_sync(kind)
    dt = (time.perf_counter() - t0) * 1e3
    slot = COMM_ACC.setdefault(name, [0, 0.0])
    slot[0] += 1
    slot[1] += dt
    return ret


OP_NAMES = ("all_reduce", "reduce_scatter_tensor", "all_gather_into_tensor",
            "broadcast", "all_gather", "reduce_scatter", "barrier",
            "_reduce_scatter_base", "_all_gather_base")


def install_comm_timers(kind):
    import torch.distributed as dist

    def wrap(name):
        orig = getattr(dist, name)

        def timed(*a, **kw):
            return _timed_call(name, orig, kind, a, kw)

        setattr(dist, name, timed)

    for name in OP_NAMES:
        if hasattr(dist, name):
            wrap(name)


def install_ds_comm_timers(kind):
    """DeepSpeed's ZeRO-3 param fetch goes through deepspeed.comm, which can
    bypass the module-level torch.distributed wrappers; wrap it too. The
    depth guard prevents double counting when one layer calls the other."""
    try:
        import deepspeed.comm as dscomm
    except Exception:
        return

    def wrap(mod, name):
        orig = getattr(mod, name)

        def timed(*a, **kw):
            return _timed_call(name.lstrip("_"), orig, kind, a, kw)

        setattr(mod, name, timed)

    for name in OP_NAMES + ("allgather_fn", "reduce_scatter_fn", "inference_all_reduce"):
        if hasattr(dscomm, name):
            wrap(dscomm, name)
